        this.addAnnotation((ENamedElement)this.getIoHwAbstractionServerAnnotation_FailureMonitoring(), source, new String[]{"documentation", "This is only applicable in SET operations. If it is enabled, the IoHwAbstraction layer will monitor the result of the operation and issue an diagnostic signal. This means especially, that an additional client-server port has to be created. Tools can use this information to cross-check whether for each data-element in a SET operation with FailureMonitoring enabled an additional port is created\r\n\r\nThe referenced port monitors a failure in the to be monitored data-element of the IoHwAbstraction layer. The referenced port has to be another port of the same Actuator or Sensor Component."});
        this.addAnnotation((ENamedElement)this.getIoHwAbstractionServerAnnotation_FilteringDebouncing(), source, new String[]{"documentation", "This attribute is used to indicate what kind of filtering/debouncing has been put to the signal in the IoHwAbstraction layer. \r\n\r\nrawData means that no modification of the signal has been applied.This is the default value\r\ndebounceData means that the signal is a mean value\r\nwaitTimeData means that the signal is delivered by a GET operation after a certain amount of time\r\n"});
