        this.addAnnotation((ENamedElement)this.processingKindEEnum, source, new String[]{"documentation", "Kind of processing which has ben applied to a data element."});
        this.addAnnotation((ENamedElement)this.processingKindEEnum.getELiterals().get(0), source, new String[]{"documentation", "Indicates that none of the other option apply."});
        this.addAnnotation((ENamedElement)this.processingKindEEnum.getELiterals().get(1), source, new String[]{"documentation", "Specifies that a signal is taken directly from the basic software modules, i.e. from the ECU abstraction layer. It indicates to a developer that the control algorithm in the software has to provide filters. "});
